parameters.functionScript:
if (Inputs.slug === undefined) return;
let current = Inputs.current;
if (current === undefined && Noodl && Noodl.Variables) {
  current = Noodl.Variables["siteCurrentSlug"];
}
const isCurrent = current !== undefined && current !== null && current !== '' && String(current) === String(Inputs.slug);
Outputs.color = isCurrent ? 'var(--primary)' : 'var(--muted-foreground)';
Outputs.weight = isCurrent ? 'var(--font-semibold)' : 'var(--font-normal)';
Outputs.current = isCurrent;

const kind = Inputs.kind || 'richText';
const d = Inputs.data || {};
const body = d.body || '';
const image = (d.image && d.image.url) || '';
Outputs.showImage = image !== '' && (kind === 'hero' || kind === 'gallery');
Outputs.showBody = body !== '' && kind !== 'gallery';
Outputs.body = body;
Outputs.image = image;
Outputs.weight = (kind === 'hero' || kind === 'cta') ? 'var(--font-bold)' : 'var(--font-normal)';
Outputs.size = kind === 'hero' ? 'var(--text-3xl)' : 'var(--text-base)';
Outputs.family = kind === 'hero' ? 'var(--font-serif)' : 'var(--font-sans)';

const name = Inputs.name || "";
const email = Inputs.email || "";
const message = Inputs.message || "";
if (name === '' || email === '' || message === '') return;
Outputs.name = name;
Outputs.email = email;
Outputs.message = message;
Outputs.pageSlug = Inputs.pageSlug || '';
Outputs.go();

const pageRefused = Inputs.error !== undefined && Inputs.error !== null && Inputs.error !== "";
const settingsRefused = Inputs.settingsError !== undefined && Inputs.settingsError !== null && Inputs.settingsError !== "";
if (settingsRefused) {
  Outputs.text = "This site’s pages are not available right now.";
  Outputs.visible = true;
  return;
}
if (Inputs.claimed === false) {
  Outputs.text = "This site has not been set up yet.";
  Outputs.visible = true;
  return;
}
if (pageRefused) {
  Outputs.text = "This site’s pages are not available right now.";
  Outputs.visible = true;
  return;
}
if (Inputs.watchdog !== undefined && Inputs.claimed === undefined && Inputs.missing === undefined) {
  Outputs.text = "No backend connected. This project needs a backend before it can store pages — add one from Backend Services.";
  Outputs.visible = true;
  return;
}
if (Inputs.missing === undefined) return;
if (!Inputs.missing) {
  Outputs.visible = false;
  return;
}
Outputs.text = "That page could not be found.";
Outputs.visible = true;

const rows = Inputs.rows || [];
const first = rows[0] ? rows[0].data || rows[0] : {};
Outputs.siteName = first.siteName || '';
Outputs.claimed = rows.length > 0;
Outputs.homeSlug = first.homeSlug || 'home';

if (Inputs.homeSlug === undefined) return;
const fromUrl = Inputs.slug === undefined || Inputs.slug === null ? '' : String(Inputs.slug);
const slug = fromUrl === '' ? Inputs.homeSlug : fromUrl;
if (slug === '') return;
Outputs.slug = slug;
if (Noodl && Noodl.Variables) {
  Noodl.Variables["siteCurrentSlug"] = slug;
}
Outputs.ready();

if (Inputs.rows === undefined) return;
const rows = Inputs.rows || [];
const row = rows[0];
const d = row ? row.data || row : undefined;
Outputs.missing = d === undefined;
Outputs.title = d ? d.title || '' : '';
Outputs.seoDescription = d ? d.seoDescription || '' : '';
Outputs.slug = d ? d.slug || '' : '';
if (d === undefined) return;
Outputs.pageId = row.getId ? row.getId() : (d.objectId || '');
Outputs.found();

if (Inputs.rows === undefined) return;
const rows = Inputs.rows || [];
Outputs.hasContact = rows.some(function (r) {
  const d = r.data || r;
  return d.kind === 'contact';
});

if (typeof document === 'undefined') return;
const rows = Inputs.rows || [];
const first = rows[0] ? rows[0].data || rows[0] : {};
const t = first.tokens || {};
const root = document.documentElement;
if (t.colorPrimary) {
  root.style.setProperty('--primary', t.colorPrimary);
  root.style.setProperty('--primary-hover', 'color-mix(in srgb, ' + t.colorPrimary + ' 82%, black)');
  root.style.setProperty('--ring', t.colorPrimary);
  root.style.setProperty('--accent-foreground', t.colorPrimary);
}
if (t.colorOnPrimary) root.style.setProperty('--primary-foreground', t.colorOnPrimary);
if (t.colorBackground) root.style.setProperty('--background', t.colorBackground);
if (t.colorSurface) {
  root.style.setProperty('--surface', t.colorSurface);
  root.style.setProperty('--surface-raised', t.colorSurface);
}
if (t.colorText) root.style.setProperty('--foreground', t.colorText);
if (t.colorTextSoft) root.style.setProperty('--muted-foreground', t.colorTextSoft);
if (t.colorBorder) {
  root.style.setProperty('--border', t.colorBorder);
  root.style.setProperty('--border-subtle', 'color-mix(in srgb, ' + t.colorBorder + ' 45%, var(--background))');
  root.style.setProperty('--border-strong', 'color-mix(in srgb, ' + t.colorBorder + ' 65%, var(--foreground))');
}
if (t.colorAccentSoft) root.style.setProperty('--accent', t.colorAccentSoft);
if (t.radius) root.style.setProperty('--radius-md', t.radius);
if (t.fontDisplay) root.style.setProperty('--font-serif', t.fontDisplay);
if (t.fontUi) {
  root.style.setProperty('--font-sans', t.fontUi);
  root.style.fontFamily = t.fontUi;
}
if (t.measure) root.style.setProperty('--site-measure', t.measure);

if (!Inputs.title) return;
if (!Noodl || !Noodl.SEO) return;
Noodl.SEO.setTitle(Inputs.title);

const active = Inputs.active || '';
const colour = (k) => (active === k ? 'var(--primary)' : 'var(--foreground)');
const weight = (k) => (active === k ? 'var(--font-semibold)' : 'var(--font-normal)');
Outputs.pagesColor = colour("pages");
Outputs.pagesWeight = weight("pages");
Outputs.themeColor = colour("theme");
Outputs.themeWeight = weight("theme");
Outputs.messagesColor = colour("messages");
Outputs.messagesWeight = weight("messages");

const d = Inputs.data || {};
Outputs.body = d.body || '';
Outputs.image = (d.image && d.image.url) || '';

if (Inputs.data === undefined) return;
const next = Object.assign({}, Inputs.data);
if (Inputs.body !== undefined) next.body = Inputs.body;
if (Inputs.image !== undefined && Inputs.image !== null) next.image = Inputs.image;
Outputs.data = next;
Outputs.built();

if (Inputs.pageId === undefined || Inputs.pageId === '') return;
Outputs.pageId = Inputs.pageId;
Outputs.ready();

const published = Inputs.published === true;
Outputs.label = published ? 'Published' : 'Draft';
Outputs.pillBackground = published ? 'var(--primary)' : 'var(--accent)';
Outputs.pillColor = published ? 'var(--primary-foreground)' : 'var(--muted-foreground)';

const rows = Inputs.rows || [];
const first = rows[0] ? rows[0].data || rows[0] : {};
Outputs.siteName = first.siteName || '';
Outputs.homeSlug = first.homeSlug || 'home';

const rows = Inputs.rows || [];
const first = rows[0] ? rows[0].data || rows[0] : {};
const t = first.tokens || {};
Outputs.primary = t.colorPrimary || '';
Outputs.onPrimary = t.colorOnPrimary || '';
Outputs.background = t.colorBackground || '';
Outputs.surface = t.colorSurface || '';
Outputs.text = t.colorText || '';
Outputs.textSoft = t.colorTextSoft || '';
Outputs.border = t.colorBorder || '';
Outputs.accentSoft = t.colorAccentSoft || '';
Outputs.radius = t.radius || '';
Outputs.fontDisplay = t.fontDisplay || '';
Outputs.fontUi = t.fontUi || '';
Outputs.measure = t.measure || '';

const rows = Array.isArray(Inputs.rows) ? Inputs.rows : [];
const published = rows.filter((r) => r && r.published === true).length;
const WORDS = ['No', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten'];
const word = (n) => (n < WORDS.length ? WORDS[n] : String(n));
const pages = rows.length === 1 ? 'page' : 'pages';
Outputs.sentence = word(rows.length) + ' ' + pages + ', ' + word(published).toLowerCase() + ' published';

if (Inputs.token === undefined || Inputs.token === null) return;
Outputs.token = Inputs.token;
Outputs.go();

if (Inputs.rows === undefined) return;
const rows = Inputs.rows || [];
const first = rows[0] ? rows[0].data || rows[0] : {};
const address = first.contactRecipient || Inputs.fallback;
if (address) {
  Outputs.recipient = address;
  Outputs.ready();
} else {
  Outputs.failed();
}

if (Inputs.pageId === undefined || Inputs.isPublic === undefined) return;
Outputs.pageId = Inputs.pageId;
Outputs.isPublic = Inputs.isPublic;
Outputs.ready();

if (Inputs.sections === undefined || Inputs.isPublic === undefined) return;
const flag = Inputs.isPublic;
Outputs.tasks = (Inputs.sections || []).map((s) => ({ objectId: s.id, isPublic: flag }));
Outputs.built();

if (Inputs.pageId === undefined) return;
Outputs.pageId = Inputs.pageId;
Outputs.ready();

const title = Inputs.title || 'Untitled';
const slug = Inputs.slug || 'page';
Outputs.title = 'Copy of ' + title;
Outputs.slug = slug + '-copy-' + Math.random().toString(36).slice(2, 8);
Outputs.built();

if (Inputs.sourcePageId === undefined || Inputs.newPageId === undefined) return;
Outputs.sourcePageId = Inputs.sourcePageId;
Outputs.newPageId = Inputs.newPageId;
Outputs.ready();

if (Inputs.sections === undefined || Inputs.newPageId === undefined) return;
const pageId = Inputs.newPageId;
Outputs.tasks = (Inputs.sections || []).map((s) => {
  const d = s.data || s;
  return { kind: d.kind, order: d.order, data: d.data, newPageId: pageId };
});
Outputs.built();

Outputs.subject = 'New enquiry from ' + (Inputs.name || 'a visitor');
Outputs.text = [
  'From: ' + (Inputs.name || '') + ' <' + (Inputs.email || '') + '>',
  'Page: ' + (Inputs.pageSlug || '(unknown)'),
  '',
  Inputs.message || ''
].join('\n');
Outputs.built();

if (Inputs.rows === undefined) return;
if (Inputs.expected === undefined || Inputs.supplied === undefined) return;
const expected = Inputs.expected || '';
const supplied = Inputs.supplied || '';
// Constant-time compare. A plain === leaks the matching prefix length
// through timing, and this is the one door in the template that mints
// an admin — the three extra lines are cheaper than the argument.
let diff = expected.length ^ supplied.length;
const n = Math.max(expected.length, supplied.length);
for (let i = 0; i < n; i++) {
  diff |= (expected.charCodeAt(i) || 0) ^ (supplied.charCodeAt(i) || 0);
}
// An empty expected token is never a match: an unprovisioned secret
// must not let a caller in with an empty string.
const tokenOk = expected.length > 0 && diff === 0;
if (tokenOk && Inputs.unclaimed === true) {
  Outputs.claimed = true;
  Outputs.ok();
} else {
  Outputs.denied();
}
